INSERT INTO public.kbfb_checklists (name, hms_omrade, avdeling, gjelder_for, gjentakelse, beskrivelse, items)
SELECT 'Årlig renholdsplan', 'Renhold', 'Hele barnehagen', NULL, 'Startes manuelt', 'Hovedrengjøring', '[{"id":1,"text":"Vask av veggflater."},{"id":2,"text":"Støvsuging/vask/avtørking av himlinger."},{"id":3,"text":"Skuring og polishbehandling av harde og halvharde gulvflater."},{"id":4,"text":"Vask av gardiner."}]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.kbfb_checklists WHERE name = 'Årlig renholdsplan');

INSERT INTO public.kbfb_checklists (name, hms_omrade, avdeling, gjelder_for, gjentakelse, beskrivelse, items)
SELECT 'Sikkerhet på tur', 'Barn og sikkerhet', 'Hele barnehagen', NULL, 'Startes manuelt', 'Sjekklisten kan gjennomgås før hver tur slik at barnehagen forsikrer seg om at sikkerheten er ivaretatt', '[{"id":1,"text":"Det er gitt beskjed til gjenværende personale om hvem som går og hvor turgruppen drar."},{"id":2,"text":"Oppdatert telleliste av barna er med."},{"id":3,"text":"Alle barn har på seg refleksvester med navn og telefonnummer til bhg."},{"id":4,"text":"Mobiltelefon er med."},{"id":5,"text":"Ansatte som drar på tur har nødvendig førstehjelpkompetanse og nødvendig førstehjelpsutstyr er med."},{"id":6,"text":"Ansatte er i stand til å forklare hvor de befinner seg i tilfelle behov for ambulanse."},{"id":7,"text":"Medisiner ved behov er med (allergi, astma, diabetes o.l)."}]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.kbfb_checklists WHERE name = 'Sikkerhet på tur');

INSERT INTO public.kbfb_checklists (name, hms_omrade, avdeling, gjelder_for, gjentakelse, beskrivelse, items)
SELECT 'Revisjon av HMS-arbeidet', 'Internkontroll', 'Hele barnehagen', NULL, 'Startes manuelt', 'Sjekklisten kan brukes til å gjennomføre en internrevisjon av HMS-systemet, for å kartlegge om praksisen samsvarer med internkontrollforskriften § 5. Internrevisjonen skal danne grunnlaget for den videre utviklingen av barnehagens HMS-system.', '[{"id":1,"text":"Har barnehagen tilgang og kjennskap til gjeldende myndighetskrav?"},{"id":2,"text":"Har ansatte kjennskap til HMS-arbeidet, og får de informasjon om eventuelle endringer i HMS-systemet?"},{"id":3,"text":"Har ledelsen, verneombud, ansatte, nyansatte og vikarer nødvendig opplæring innen helse, miljø og sikkerhet?"},{"id":4,"text":"Er det tilrettelagt for at ansatte kan medvirke slik at samlet kunnskap og erfaring utnyttes? (eks. personalmøter, avdelingsmøter o.l.)"},{"id":5,"text":"Er overordnet HMS målsetning fortsatt relevant, og formidlet til alle ansatte?"},{"id":6,"text":"Er konkret og målbart HMS-mål for inneværende år valgt, og formidlet til alle ansatte?"},{"id":7,"text":"Har barnehagen evaluert oppnåelsen av fjorårets konkrete HMS-mål?"},{"id":8,"text":"Er organisasjonskart, og fordeling av ansvarsområder innen HMS-arbeidet oppdatert?"},{"id":9,"text":"Er arbeidsforholdene for de ansatte risikovurdert? (ergonomi, støy, inneklima, smittevern, organisatorisk og psykososialt arbeidsmiljø)"},{"id":10,"text":"Er miljøet for barna og sikkerheten til barna risikovurdert? (psykososialt miljø, nye turmål, ute- og inneområdet)"},{"id":11,"text":"Er tiltak for å redusere risikoforhold fulgt opp i tiltaksplanen?"},{"id":12,"text":"Fungerer gjennomføring av vernerunder?"},{"id":13,"text":"Fungerer system for avviksmeldinger i praksis?"},{"id":14,"text":"Har barnehagen evaluert fjorårets avviksmeldinger og utførte tiltak?"},{"id":15,"text":"Er beredskapsrutinene og beredskapskortene oppdatert?"},{"id":16,"text":"Har barnehagen gjennomført og brann- og beredskapsøvelsene?"},{"id":17,"text":"Fungerer HMS-rutinene for de ansatte i praksis?"},{"id":18,"text":"Fungerer HMS-rutinene for barna i praksis?"},{"id":19,"text":"Har barnehagen gjennomgått vedlikeholdsplanen?"},{"id":20,"text":"Er stoffkartoteket oppdatert?"},{"id":21,"text":"Har barnehagen evaluert og gjennomgått sykefraværsstatistikken?"},{"id":22,"text":"Er HMS-aktiviteter for kommende periode planlagt?"}]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.kbfb_checklists WHERE name = 'Revisjon av HMS-arbeidet');

INSERT INTO public.kbfb_checklists (name, hms_omrade, avdeling, gjelder_for, gjentakelse, beskrivelse, items)
SELECT 'Personvern', 'Personvern', 'Hele barnehagen', NULL, 'Startes manuelt', 'Denne sjekklisten kan benyttes til en kontroll/vernerunde av personvernhåndteringen i barnehagen.', '[{"id":1,"text":"Vi har skriftlige rutiner for hvordan vi innhenter, lagrer og sletter personopplysninger."},{"id":2,"text":"Alle ansatte har fått opplæring i hvordan vi skal behandle personopplysninger og ivareta taushetsplikten."},{"id":3,"text":"Foresatte informeres om hvilke personopplysninger vi innhenter, og hvordan vi oppbevarer dem."},{"id":4,"text":"Vi innhenter skriftlig samtykke fra foresatte ved deling av bilder, video og adresselister."},{"id":5,"text":"Vi innhenter skriftlig samtykke når vi skal samarbeide med PPT eller andre tredjeparter."},{"id":6,"text":"Vi innhenter skriftlig samtykke når vi skal dele informasjon med skolen i forbindelse med skolestart."},{"id":7,"text":"Alle personopplysningene tilknyttet et barn, lagres i barnemappen."},{"id":8,"text":"Det er bare ansatte som direkte jobber med barna, som har tilgang til barnemappen."},{"id":9,"text":"Barnemappen er utilgjengelig for uvedkommende."},{"id":10,"text":"Vi har rutine for å se gjennom og oppdatere barnemappen og personalmappen."},{"id":11,"text":"Vi har utført en risikovurdering av personvernhåndteringen i barnehagen."},{"id":12,"text":"Vi skriver avvik, dersom personvernrutinene blir brutt."},{"id":13,"text":"Vi har rutine for at alle avvik knyttet til personvernhåndtering av en viss alvorlighet, meldes til datatilsynet innen 72 timer."},{"id":14,"text":"Når et barn slutter, gjennomgår vi opplysningene vi har lagret om barnet og de foresatte. Som hovedregel sletter vi bilder, E-post logg, dokumenter og registreringer vi har gjort."},{"id":15,"text":"Når ansatte slutter i barnehagen, gjennomgår vi personalmappen og sletter det vi ikke lengre har behandlingsgrunnlag for."},{"id":16,"text":"Vi har laget en oversikt over alle datasystemene vi bruker som behandler personopplysninger."},{"id":17,"text":"Vi har inngått en databehandleravtale med leverandører av datasystemene som oppbevarer personopplysninger."}]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.kbfb_checklists WHERE name = 'Personvern');

INSERT INTO public.kbfb_checklists (name, hms_omrade, avdeling, gjelder_for, gjentakelse, beskrivelse, items)
SELECT 'Mathåndtering', 'IK Mat', 'Hele barnehagen', NULL, 'Startes manuelt', 'Sjekkliste til bruke ved revisjon eller revidering av IK Mat-rutiner. Sjekklisten er basert på kravene næringsmiddellovgivningen.', '[{"id":1,"text":"Stilles det krav til dokumentasjon fra leverandør?"},{"id":2,"text":"Foretas det kontroll av matvarer ved mottak (temperatur, emballasje)?"},{"id":3,"text":"Blir matvarene umiddelbart tatt hånd om ved levering?"},{"id":4,"text":"Praktiseres det varerullering (ferskeste matvarer plasseres bakerst)?"},{"id":5,"text":"Registreres kjøleskapstemperatur (daglig) og frysetemperatur (ukentlig)?"},{"id":6,"text":"Merkes mat som fryses ned med dato for nedfrysning?"},{"id":7,"text":"Er kantinen oppmerksom på at kjøleskapsmatvarer ikke skal oppbevares i romtemperatur lengre enn to timer?"},{"id":8,"text":"Kastes mat som er gått ut på dato?"},{"id":9,"text":"Har ansatte som jobber på kjøkkenet hatt opplæring?"},{"id":10,"text":"Brukes det forkle ved mathåndtering?"},{"id":11,"text":"Tines frosne matvarer i kjøleskap?"},{"id":12,"text":"Håndteres rå og behandlede matvarer separat?"},{"id":13,"text":"Er skjærefjølene hele, og av plast?"},{"id":14,"text":"Brukes det ulike skjærefjøler til grønnsaker, kjøtt og fisk?"},{"id":15,"text":"Har kantinen rutiner for hvordan matallergier blir ivaretatt på kjøkkenet?"},{"id":16,"text":"Porsjoneres pålegget ut i små porsjoner når det settes frem på bordet?"},{"id":17,"text":"Holder varmmat en temperatur på minst 60 grader ved servering?"},{"id":18,"text":"Fordeles varmmat i mindre bakker og nedkjøles på under to timer?"}]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.kbfb_checklists WHERE name = 'Mathåndtering');

INSERT INTO public.kbfb_checklists (name, hms_omrade, avdeling, gjelder_for, gjentakelse, beskrivelse, items)
SELECT 'Kvartalsvis ettersyn lekeplassutstyr/utelekeområdet', 'Barn og sikkerhet', 'Hele barnehagen', NULL, 'Den andre mandag hver tredje måned', 'Sjekklisten kan bukes i forbindelse med ettersyn av lekeplassustyret.', '[{"id":1,"text":"Utelekeområdet er forsvarlig inngjerdet med tanke på høyde og tilstand på materialet (ingen spikrer eller lignende som stikker ut)."},{"id":2,"text":"Inngjerdingen er forsvarlig med tanke på at det ikke er klatrebart."},{"id":3,"text":"Bakken er godt drenert, slik at det ikke oppstår varige vannstander på 10 cm eller dypere."},{"id":4,"text":"Overflatene er fri for rustne spiker."},{"id":5,"text":"Utelekeområdet er fritt for stikkende busker og andre giftige planter."},{"id":6,"text":"Det er tilstrekkelig mengde (iht. produsentens anbefaling) falldempende underlag under alle lekeapparatene hvor det kreves (påkrevd ved fallhøyde over 60 cm)."},{"id":7,"text":"Alle støpte fundamenter til lekeapparatene godt tildekt med fyllmasse."},{"id":8,"text":"Det er forsvarlige og frie sikkerhetssoner rundt hvert lekeapparat (lav risiko for kollisjon med andre apparater, fritt for stein og andre forstyrrende elementer)."},{"id":9,"text":"Alle lekeapparatene/konstruksjonene er tilstrekkelig festet (sjekk kjettinger, fester, oppheng på husker osv.)."},{"id":10,"text":"Alle lekeapparatene er uten skadelig rust, råteskader eller annen form for slitasjeskader."},{"id":11,"text":"Alle bolter og skruer er godt festet og strammet."},{"id":12,"text":"Alle rekkverk, håndlister, trapper og ramper tilknyttet lekehus, klatrestativer og rutsjebaner er i orden."},{"id":13,"text":"Lekeapparatene er tilstrekkelig rengjort."},{"id":14,"text":"Ingen lekeapparater har utstikkende deler eller skarpe kanter som barna kan skade seg på."},{"id":15,"text":"Det finnes ingen v-formede åpninger hvor snorer, hetter og andre klær kan sette seg fast ved rutsjebaneutløpet eller i selve rutsjebanen."},{"id":16,"text":"Overflaten på sklien er i en slik stand at den er fri for utstikkende deler hvor klær kan henge seg fast."}]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.kbfb_checklists WHERE name = 'Kvartalsvis ettersyn lekeplassutstyr/utelekeområdet');

INSERT INTO public.kbfb_checklists (name, hms_omrade, avdeling, gjelder_for, gjentakelse, beskrivelse, items)
SELECT 'Kjemikaliehåndtering', 'Kjemikalier', 'Hele barnehagen', NULL, 'Startes manuelt', 'Sjekklisten kan brukes for å kontrollere at barnehagen har gode rutiner for håndtering av kjemikalier i barnehagen', '[{"id":1,"text":"Barnehagen har oversikt over hvilke kjemikalier/vaskeprodukter som oppbevares i barnehagen."},{"id":2,"text":"Barnehagen har risikovurdert uønskede hendelser (barn og ansatte) knyttet til kjemikaliehåndtering i barnehagen."},{"id":3,"text":"Alle kjemikalier er merket."},{"id":4,"text":"Vårt stoffkartotek med sikkerhetsdatablader er oppdatert, og alle er informert om hvor dette er tilgjengelig."},{"id":5,"text":"Alle kjemikalier som ikke oppbevares i orginalemballasjen merkes."},{"id":6,"text":"Stoffkartoteket oppbevares tilgjengelig for ansatte."},{"id":7,"text":"Ansatte har hatt opplæring i hvilke kjemikalier som er mest helsefarlig og i bruk av stoffkartoteket."},{"id":8,"text":"Kjemikaliene opbevares utilgjengelig for barn (låst skap eller så høyt oppe at det er uten adkomstmulighet for barn)."}]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.kbfb_checklists WHERE name = 'Kjemikaliehåndtering');

INSERT INTO public.kbfb_checklists (name, hms_omrade, avdeling, gjelder_for, gjentakelse, beskrivelse, items)
SELECT 'Innhold førstehjelpsskrin', 'Førstehjelp', 'Hele barnehagen', NULL, 'Startes manuelt', 'Sjekklisten kan brukes når førstehjelpsskrinet skal kontrollerers for innhold', '[{"id":1,"text":"To pk. komprimerende bandasjer (enkeltmannspakninger)"},{"id":2,"text":"To pk. sterile kompress"},{"id":3,"text":"To pk. absorberende kompress"},{"id":4,"text":"To pk. gasbind"},{"id":5,"text":"En pk. sårplaster"},{"id":6,"text":"En rull heftplaster eller lignende"},{"id":7,"text":"To pk. sterile tupfere"},{"id":8,"text":"En pk. trekanttørkle"},{"id":9,"text":"En eske sikkerhetsnåler"},{"id":10,"text":"En kraftig saks til oppklipping av tøy"},{"id":11,"text":"Pinsett"},{"id":12,"text":"En rull elastisk bind"},{"id":13,"text":"En munn-til-munn duk"},{"id":14,"text":"Et øyeskylleglass"},{"id":15,"text":"To flasker øyeskyllevann/fysiologisk saltvann"},{"id":16,"text":"Brannbandasje"},{"id":17,"text":"Medisinsk kull"},{"id":18,"text":"Kort førstehjelpsveiledning"},{"id":19,"text":"Sårvaskeservietter/pyrisept eller lignende"}]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.kbfb_checklists WHERE name = 'Innhold førstehjelpsskrin');

INSERT INTO public.kbfb_checklists (name, hms_omrade, avdeling, gjelder_for, gjentakelse, beskrivelse, items)
SELECT 'Inneklima', 'Inneklima', 'Hele barnehagen', NULL, 'Startes manuelt', 'Sjekklisten kan brukes til en årlig revisjon/vernerunde på inneklimaet i barnehagen', '[{"id":1,"text":"Det er god ventilasjon/friskluftstilførsel til bygget"},{"id":2,"text":"Temperaturen i barnehagen er god (anbefalt temp 20-22 grader)"},{"id":3,"text":"Barnehagen er ryddig og har god orden"},{"id":4,"text":"Renholdet i barnehagen er godt"},{"id":5,"text":"Bruker ansatte mopp i stedet for feiekost når sand, bøss og matsmuler skal fjernes fra gulvet?"},{"id":6,"text":"Det finnes ingen større støvoppsamlinger i barnehagen"},{"id":7,"text":"Det finnes dørmatter ved alle inngangspartier for å hindre at sand og bøss dras med inn"},{"id":8,"text":"Det brukes grovkornet sand om vinteren for å redusere mengden sandkorn som dras med inn i barnehagen"},{"id":9,"text":"Det finnes ingen tegn til fukt eller fuktskader i bygget"},{"id":10,"text":"Det benyttes kjøkkenvifte med avtrekk under varmmatstilberedning"},{"id":11,"text":"Barnehagen oppbevarer ingen allergifremkallende planter"},{"id":12,"text":"Det er foretatt tilfredsstillende radonmåling i løpet av de siste 5 årene"},{"id":13,"text":"Det er ikke behov for bygningsmessig vedlikehold/utbedringer for å kunne ivareta et tilfredsstillende inneklima"},{"id":14,"text":"Belysningen i alle rom oppleves som tilfredsstillende"},{"id":15,"text":"Lyd og støyforhold oppleves som tilfredsstillende i barnehagen"}]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.kbfb_checklists WHERE name = 'Inneklima');

INSERT INTO public.kbfb_checklists (name, hms_omrade, avdeling, gjelder_for, gjentakelse, beskrivelse, items)
SELECT 'Hygiene og smittevern', 'Hygiene og smittevern', 'Hele barnehagen', NULL, 'Startes manuelt', 'Sjekklisten kan benyttes for å få oversikt over hygiene- og smittevernarbeidet i barnehagen.', '[{"id":1,"text":"Foresatte og nyansatte er informert og opplært i våre hygiene- og smittevernrutiner."},{"id":2,"text":"Vi har såpedispensere og papirtørk lett tilgjengelig ved alle vasker."},{"id":3,"text":"Vi har hånddesinfeksjon tilgjengelig der vi ikke har tilgang på såpe og vann og har med på tur."},{"id":4,"text":"Vi har ren og uren sone på stellerom."},{"id":5,"text":"Vi har engangshansker og engangs stellelaken/ rene håndklær tilgjengelig på stellerom."},{"id":6,"text":"Vi har risikovurdert smitte i barnehagen."},{"id":7,"text":"Vi har rutine for håndhygiene og lærer opp barn og nyansatte i håndvask."},{"id":8,"text":"Vi har rutiner for søppelhåndtering."},{"id":9,"text":"Vi har rutine for renhold og renhold kjøkken."},{"id":10,"text":"Vi har rutine for mathåndtering."},{"id":11,"text":"Vi har rutine for håndtering av blodsøl og kroppsvæsker."},{"id":12,"text":"Vi har rutine for kontakt med dyr."},{"id":13,"text":"Vi har rutine for skadedyr."},{"id":14,"text":"Vi har rutine for smittsomme sykdommer."},{"id":15,"text":"Ved utbrudd av smittsomme sykdommer iverksetter vi skjerpende hygienerutiner."},{"id":16,"text":"Vi følger Folkehelseinstituttet sine retningslinjer for når syke barn bør være hjemme fra barnehagen, se vedlegg til rutine \"smittsomme sykdommer\"."}]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.kbfb_checklists WHERE name = 'Hygiene og smittevern');

INSERT INTO public.kbfb_checklists (name, hms_omrade, avdeling, gjelder_for, gjentakelse, beskrivelse, items)
SELECT 'Hygiene og renhold kjøkken', 'IK Mat', 'Hele barnehagen', NULL, 'Startes manuelt', 'Sjekklisten kan brukes for å kontrollere at barnehagens kjøkkenlokale er er forsvarlig utformet av hensyn til mattryggheten', '[{"id":1,"text":"Har kjøkkenet glatte og rene flater slik at det er enkelt å gjøre rent?"},{"id":2,"text":"Har kjøkkenet et tydelig skille mellom ren og uren sone?"},{"id":3,"text":"Har kjøkkenet egen håndvask som er hensiktsmessig plassert (kan kombineres med utslagsvask)?"},{"id":4,"text":"Kan håndvasken betjenes uten bruk hender?"},{"id":5,"text":"Er såpedispenser/desinfeksjonsdispenser og papirtørk hensiktsmessig montert i forhold til håndvasken?"},{"id":6,"text":"Har kjøkkenet godt lys?"},{"id":7,"text":"Skylles frukt og grønt i en egen vask, eventuelt egen balje?"},{"id":8,"text":"Skilles det på hvor håndvask utføres og hvor vask av matvarer utføres?"},{"id":9,"text":"Har ansatte tilgang til egen garderobe og toalett?"},{"id":10,"text":"Ved egen kokk/kjøkkenpersonell, har kjøkkenpersonalet tilgang til eget toalett?"},{"id":11,"text":"Har kjøkkenet tilfredsstillende ventilasjon og avtrekk?"},{"id":12,"text":"Har kjøkkenet egnet oppvaskmaskin som holder en temperatur på 75 grader ved skylling?"},{"id":13,"text":"Har barnehagen renholdsplan for kjøkken?"},{"id":14,"text":"Byttes kjøkkenkluten etter hvert måltid?"},{"id":15,"text":"Blir oppvaskbørsten vasket i oppvaskmaskinen /event. kloret ved jevne mellomrom?"},{"id":16,"text":"Er det ryddig og god orden utenfor barnehagen og på barnehagens lager?"},{"id":17,"text":"Er alle byggekonstruksjoner tette slik at ingen skadedyr kan trenge seg inn?"},{"id":18,"text":"Er det tilstrekkelig med avfallsbeholdere med lokk innendørs og utendørs?"},{"id":19,"text":"Blir avfallsbeholdere rengjort jevnlig?"},{"id":20,"text":"Har barnehagen rutine for kontroll og vedlikehold av kjøkkensutstyr? (alt fra fjøler og kasseroller til utstyr som oppvaskmaskin og komfyr)"}]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.kbfb_checklists WHERE name = 'Hygiene og renhold kjøkken');

INSERT INTO public.kbfb_checklists (name, hms_omrade, avdeling, gjelder_for, gjentakelse, beskrivelse, items)
SELECT 'Ergonomi', 'Arbeidsmiljø', 'Hele barnehagen', NULL, 'Startes manuelt', 'Denne sjekklisten brukes for å forebygge muskel- og skjelettplager hos ansatte i barnehagen.', '[{"id":1,"text":"Arbeidet er organisert og tilrettelagt med hensyn til den enkelte arbeidstakers forutsetninger."},{"id":2,"text":"Arbeidsoppgaver er fordelt slik at arbeidstakere gis mulighet til variasjon."},{"id":3,"text":"Arbeidstakere får avvikle pause i løpet av arbeidsdagen."},{"id":4,"text":"Avdelingene samarbeider og hjelper hverandre ved behov."},{"id":5,"text":"Barnehagen har skriftlig rutine for mottak, opplæring og bruk av vikarer."},{"id":6,"text":"Barnehagen har gravidepolitikk som er kjent for de ansatte."},{"id":7,"text":"Alle ansatte får lovpålagt opplæring i ergonomi."},{"id":8,"text":"Alle ansatte har fått informajson om ergonomiske risikofaktorer."},{"id":9,"text":"Barnehagens fysiske arbeidsmiljøforhold (bygning, utstyr, støy, inneklima, lysforhold) er fullt forsvarlig for de ansattes helse, miljø, sikkerhet og velferd."},{"id":10,"text":"Barnehagen er innredet og utformet slik at man unngår uheldige belastninger."},{"id":11,"text":"Arbeidstakere har nødvendige hjelpemidler til disposisjon."},{"id":12,"text":"Barnehagen har kartlagt, risikovurdert og utarbeidet tiltak for forebygging av muskel- og skjelettplager i barnehagen."},{"id":13,"text":"Arbeidstakere medvirker i risikovurdering av de ergonomiske forholdene i barnehagen."},{"id":14,"text":"Arbeidsgiver gjennomfører nødvendige tiltak for å fjerne eller redusere risiko for belastning, herunder utviklingstiltak."},{"id":15,"text":"Pedagogiske ledere følger opp tiltak på sin avdeling for å forebygge muskel- og skjelettplager."},{"id":16,"text":"Barnehagen jobber forebyggende og helsefremmende for å sikre et godt fysisk og psykososialt arbeidsmiljø."},{"id":17,"text":"Arbeidstakere ber om en samtale med leder når de kjenner behov for tilrettelegging av arbeidet eller står i fare for å bli sykemeldt."},{"id":18,"text":"Barnehagen tilrettelegger for ansatte som står i fare for å bli sykemeldt/er sykemeldt."},{"id":19,"text":"Barnehagen tilbyr arbeidsplassvurdering ved BHT for arbeidstakere som har muskel- og skjelettplager."}]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.kbfb_checklists WHERE name = 'Ergonomi');

INSERT INTO public.kbfb_checklists (name, hms_omrade, avdeling, gjelder_for, gjentakelse, beskrivelse, items)
SELECT 'Egenkontroll EL-sikkerhet', 'Brannvern og elsikkerhet', 'Hele barnehagen', 'Barn, Ansatt', 'Startes manuelt', 'Sjekkliste utføres av eier/ daglig leder', '[{"id":1,"text":"Inntakssikringene er intakte"},{"id":2,"text":"Ingen av inntakssikringene er unormalt varme"},{"id":3,"text":"Inntakssikringene er godt tilskrudd"},{"id":4,"text":"Sikringene og annet utstyr i sikringsskapet er godt merket"},{"id":5,"text":"Det er satt inn riktige sikringer i henhold til merkingen på kursoversikt"},{"id":6,"text":"Sikringene i sikringsskapet er godt tilskrudd"},{"id":7,"text":"Sikringene eller annet utstyr i sikringsskapet er ikke unormalt varme"},{"id":8,"text":"Det er ikke sikringer som stadig ryker"},{"id":9,"text":"Testknappen på jordfeilbryteren eller jordfeilvarselen fungerer"},{"id":10,"text":"Ingen ledninger er løsnet eller skadet"},{"id":11,"text":"Skjøteledninger brukes minst mulig"},{"id":12,"text":"Ved bruk av skjøteledning skjer dette i samme rom som de er tilkoblet"},{"id":13,"text":"Vaskemaskin, kjøleskap, fryser eller varmeovner er ikke tilkoblet med skjøteledning"},{"id":14,"text":"Skjøteledninger som brukes ute fjernes straks etter bruk"},{"id":15,"text":"Elektrisk utstyr og apparater fungerer som de skal"},{"id":16,"text":"Varmeovner eller elektriske apparater er ikke tildekket"},{"id":17,"text":"Elektrisk utstyr brukes kun på dagtid og under tilsyn"},{"id":18,"text":"Filter/støvfilter i tørketrommel/ vifteovn/kjøkkenvifte og lignende rengjøres regelmessig"},{"id":19,"text":"Brytere, stikkontakter, støpsler, koplingsbokser eller lignende er ikke varme eller brunsvidde. Sjekk spesielt varmtvannsprederen"},{"id":20,"text":"Løse lamper eller flyttbare ovner brukes ikke hvor barna oppholder seg"},{"id":21,"text":"Korrekt lysstyrke på lyspærer er satt inn i lamper"},{"id":22,"text":"Kontaktene til kaffetrakter, mobillader, el-sykkel og lignende tas ut når arbeidsdagen er over"},{"id":23,"text":"Lading av el-bil gjøres kun i godkjente støpsler/ladestasjoner i barnehagen"},{"id":24,"text":"Fastmontert utstyr (varmeovner, lysarmaturer ol) sitter fast i underlaget"},{"id":25,"text":"Elektrisk installasjoner er utført og dokumentert (etter 1999) av elektroentreprenør"},{"id":26,"text":"Støpsler til forbruksapparater (komfyr, frysere, kjøleskap og lignende) som står tilkoblet over lang tid, er i orden"}]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.kbfb_checklists WHERE name = 'Egenkontroll EL-sikkerhet');

INSERT INTO public.kbfb_checklists (name, hms_omrade, avdeling, gjelder_for, gjentakelse, beskrivelse, items)
SELECT 'Egenkontroll av bygg', 'Bygg og vedlikehold', 'Hele barnehagen', NULL, 'Startes manuelt', 'Denne sjekklisten utføres årlig av representant fra dugnadskomiteen/HMS ansvarlig og DL. Områder som gjennomgås er fasade, tak, hems, innvendig, ventilasjon og kjøkken/våtrom.', '[{"id":1,"text":"Er det skader eller avflassingav maling/lakk?"},{"id":2,"text":"Finnes det tegn til fukt/råte som misfarging av materialer etc.?"},{"id":3,"text":"Er dekkbord på dører og vinduer intakt?"},{"id":4,"text":"Er det sprekker eller misfarging/flekker/saltutslag på grunnmur?"},{"id":5,"text":"Vender taknedløpet bort fra grunnmur slik at vannet renner bort fra bygget?"},{"id":6,"text":"Er ytterdører fri for skade (lett å lukke, er pakninger hele)?"},{"id":7,"text":"Er det rist eller gulvmatte som tar opp vann og skitt ved ytterdør?"},{"id":8,"text":"Er det skader på tak/takstein/takdekke/pipe/luftehatter som kan gi økt fare for lekkasje?"},{"id":9,"text":"Er takrenner hele og fri for løv?"},{"id":10,"text":"Er det skader eller misfarging rundt dører og vinduer inne?"},{"id":11,"text":"Er det hull eller skader i gulvbelegg?"},{"id":12,"text":"Er lokalet ryddig og innredet slik at overflater er lett å renholde?"},{"id":13,"text":"Er vinduer fri for skade (lett å lukke, pakninger er hele)?"},{"id":14,"text":"Er luftinntaket (tak/yttervegg) fritt for smuss, støv etc.?"},{"id":15,"text":"Er filteret i ventilasjonsanlegget skiftet etter serviceplanen?"},{"id":16,"text":"Er ventilasjonskanaler sjekket for smuss og støv (benytt inspeksjonsluker)?"},{"id":17,"text":"Er lufteventiler i orden og fungerer?"},{"id":18,"text":"Er det synlige skader eller misfarging rundt vannkraner/toaletter?"},{"id":19,"text":"Er det synlige skader eller misfarging under servanter/benker etc.?"},{"id":20,"text":"Er det tegn til vannlekkasje fra vaskemaskin, oppvaskmaskin, kjøleskap?"},{"id":21,"text":"Er overflatene på tak, vegg, gulv hele og uten skader?"}]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.kbfb_checklists WHERE name = 'Egenkontroll av bygg');

INSERT INTO public.kbfb_checklists (name, hms_omrade, avdeling, gjelder_for, gjentakelse, beskrivelse, items)
SELECT 'Daglig ettersyn utelekeområdet (Vår/sommer/høst)', 'Barn og sikkerhet', 'Hele barnehagen', NULL, 'Hver ukedag', 'Sjekklisten skal sikre at utelekeområdet er forsvarlig før barna slippes ut', '[{"id":1,"text":"Utelekeområdet har ingen varige vannstander som er altfor dype."},{"id":2,"text":"Alle konstruksjoner og lekeapparater er uten skader (Hærverk etc)"},{"id":3,"text":"Begge portene fungerer greit"},{"id":4,"text":"Ingen tau eller andre fremmedelementer på klatrestativene"},{"id":5,"text":"Sanden fri for fremmedelementer (Dyrebæsj, sprøyter etc)"},{"id":6,"text":"Ingen store groper under huskene"},{"id":7,"text":"Uteplassen fri for fremmedelementer, søppel. etc"},{"id":8,"text":"Ingen løse eller brekte grener på trærne"},{"id":9,"text":"Boddører låst og i orden"}]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.kbfb_checklists WHERE name = 'Daglig ettersyn utelekeområdet (Vår/sommer/høst)');

INSERT INTO public.kbfb_checklists (name, hms_omrade, avdeling, gjelder_for, gjentakelse, beskrivelse, items)
SELECT 'Brannvern', 'Brannvern og elsikkerhet', 'Hele barnehagen', 'Barn, Ansatt', 'Startes manuelt', 'Sjekkliste for brannvern', '[{"id":1,"text":"Ansatte har tilfredsstillende brannvernopplæring"},{"id":2,"text":"Brannøvelser gjennomføres i henhold til rutine"},{"id":3,"text":"Rømningsveiene er merket og uten hindringer"},{"id":4,"text":"Nødlysene fungerer"},{"id":5,"text":"Håndslukkeapparatene er i orden (synlig merket, riktig plassert, plombering intakt, trykkmanometer i orden og ingen tegn til skader)"},{"id":6,"text":"Brannslanger er i orden (skapene er lette å åpne, brannslangene er lette å trekke ut og er uten rifter/sprekker, avstengingsventiler er lette å åpne og stenge)"},{"id":7,"text":"Varslingssystemet virker som det skal"},{"id":8,"text":"Varmeovner eller annet elektrisk utstyr er ikke tildekket eller har synlige skader"},{"id":9,"text":"Det elektriske anlegget er kontrollert av fagfolk i henhold til serviceavtalen"}]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.kbfb_checklists WHERE name = 'Brannvern');

INSERT INTO public.kbfb_checklists (name, hms_omrade, avdeling, gjelder_for, gjentakelse, beskrivelse, items)
SELECT 'Barn og sikkerhet inneområdet', 'Barn og sikkerhet', 'Hele barnehagen', 'Barn', 'Startes manuelt', 'Sjekklisten skal hjelpe barnehagen med å kontrollere at sikkerheten knyttet til barna er ivaretatt', '[{"id":1,"text":"Alle ansatte har tilfredsstillende førstehjelpsopplæring"},{"id":2,"text":"Førstehjelpsskrinet er merket og oppbevares lett tilgjengelig"},{"id":3,"text":"Førstehjelpsplakater og nødnumre henger synlig på alle avdelingene"},{"id":4,"text":"Trappene er tilstrekkelig sikret med grind og har ingen åpninger i trappetrinn eller trappegelender som kan medføre kvelningsfare"},{"id":5,"text":"Vinduer har barnesikring og i luftestilling er det ikke fare for at barn kan klatre ut eller bli hengende fast"},{"id":6,"text":"De minste barna har tilsyn når de sitter i barnestol"},{"id":7,"text":"Vi har rutine for ikke å drikke varm drikke med barn på fanget og er bevisste på plassering av kaffekopper og varm væske"},{"id":8,"text":"Kaffekoker/vannkoker med ledninger er utilgjengelig for barn"},{"id":9,"text":"Vi har skåldesperre på kraner til badekar, dusj og vasker"},{"id":10,"text":"Vi har komfyrvern og barnesikring på stekeovnsdør"},{"id":11,"text":"Varmeovner og panelovner har lav overflatetemperatur"},{"id":12,"text":"Stikkontakter er barnesikret"},{"id":13,"text":"Vi er oppmerksom på snorer på klær, ryggsekker og sykkelhjelmer"},{"id":14,"text":"Det finnes ingen persienne-snorer eller rullegardin-snorer i barnehagen"},{"id":15,"text":"Lekene på avdeling er tilpasset barnets alder"},{"id":16,"text":"Vi er oppmerksom på hvor plastposer oppbevares med tanke på de minste barna"},{"id":17,"text":"Dørene er sikret for å unngå klemskader"},{"id":18,"text":"Vi har barnesikring på skuffer og skap der det er nødvendig"},{"id":19,"text":"Store og tunge gjenstander er sikret mot velt"},{"id":20,"text":"Fyrstikker, lightere, batterier, verktøy og kniver oppbevares forsvarlig"},{"id":21,"text":"Kjemikalier og medikamenter oppbevares i originalemballasje og utilgjengelig for barn"},{"id":22,"text":"Vi har oversikt over og tilsyn med barna og det er alltid voksne tilstede på avdeling"}]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.kbfb_checklists WHERE name = 'Barn og sikkerhet inneområdet');

INSERT INTO public.kbfb_checklists (name, hms_omrade, avdeling, gjelder_for, gjentakelse, beskrivelse, items)
SELECT 'Psykososialt og organisatorisk arbeidsmiljø', 'Arbeidsmiljø', 'Hele barnehagen', NULL, 'Startes manuelt', 'Denne sjekklisten kan gjennomføres av leder og verneombud sammen for å kontrollere/kartlegge det psykososiale og organisatoriske arbeidsmiljøet i barnehagen. For en grundigere kartlegging bør sjekklisten suppleres med en spørreundersøkelse til de ansatte.', '[{"id":1,"text":"Barnehagen har et oversiktlig organisasjonskart som er kjent for alle ansatte"},{"id":2,"text":"Ansvarsområdene og stillingsinstruksene til hver enkelt ansatt er klart og tydelig utformet, samt kjent og tilgjengelig for alle på arbeidsplassen"},{"id":3,"text":"Barnehagen har i personalgruppen gjennomgått hvilke forventninger som ligger til hver ansattes rolle"},{"id":4,"text":"Alle ansatte, også midlertidige ansatte, har skriftlige arbeidsavtaler"},{"id":5,"text":"Barnehagen har en langsiktig og fungerende vaktplan som er forutsigbar for alle ansatte"},{"id":6,"text":"Rutiner for avspasering og uttak av ferie fungerer godt"},{"id":7,"text":"Barnehagen har rutiner for overtid eller annet som medfører økt arbeidsbelastning"},{"id":8,"text":"Barnehagen er tilknyttet en godkjent bedriftshelsetjeneste som bistår i tråd med forskrift om organisering, ledelse og medvirkning"},{"id":9,"text":"Samarbeidet mellom barnehagens styre og daglig leder fungerer godt"},{"id":10,"text":"Barnehagen har gode beslutningsprosesser"},{"id":11,"text":"Barnehagen har gode rutiner for informasjonsutveksling mellom foreldre og ansatte"},{"id":12,"text":"Informasjonen mellom daglig leder og ansatte fungerer godt"},{"id":13,"text":"Barnehagen har tilstrekkelig antall møtepunkter for informasjonsutveksling og planlegging"},{"id":14,"text":"Det skrives møtereferater som gjøres tilgjengelig, og det gis rom for at ansatte får lest dem"},{"id":15,"text":"Barnehagen har flere gode arenaer hvor ansatte kan diskutere samarbeid og komme med tilbakemeldinger (medvirkning)"},{"id":16,"text":"Det gjennomføres jevnlige medarbeidersamtaler"},{"id":17,"text":"Barnehagen har verneombud som aktivt deltar i HMS-arbeidet"},{"id":18,"text":"Alle ansatte får tilstrekkelig opplæring når de starter å jobbe i barnehagen"},{"id":19,"text":"Alle ansatte får oppfølging og tilbud om veiledning"},{"id":20,"text":"Barnehagen har skriftlig rutine for mottak, opplæring og bruk av vikarer"},{"id":21,"text":"Arbeidsoppgavene er varierte og godt fordelt mellom ansatte"},{"id":22,"text":"Ansatte har mulighet for å ta pauser i løpet av arbeidsdagen"},{"id":23,"text":"Avdelingene samarbeider og hjelper hverandre ved behov"},{"id":24,"text":"Barnehagens pedagogiske ledere samarbeider godt og har god kommunikasjon på tvers av avdelingene"},{"id":25,"text":"Ansatte har tilstrekkelig tid til å følge opp planlagte aktiviteter"},{"id":26,"text":"Barnehagen jobber forebyggende og har gode rutiner for sykefraværsoppfølging"},{"id":27,"text":"Barnehagen tilrettelegger for ansatte som står i fare for å bli sykemeldt/er sykemeldt"},{"id":28,"text":"Barnehagen registrerer fravær og har oversikt over sykefraværet"},{"id":29,"text":"Det foreligger ingen konflikter i arbeidsmiljøet i dag som ledelsen er kjent med"},{"id":30,"text":"Barnehagen har skriftlig rutine for håndtering av konflikter og mobbing/trakassering"},{"id":31,"text":"Barnehagen har gode rutiner for varsling og håndtering av avvik"},{"id":32,"text":"Barnehagen har risikovurdert det psykososiale og organisatoriske arbeidsmiljøet"}]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.kbfb_checklists WHERE name = 'Psykososialt og organisatorisk arbeidsmiljø');

